onKey(" ", async () => {
  say("Hi!", 2);
  // lift the arm up and wave it
  await part("left arm").turnTo(150);
  await part("left arm").wiggle(3);
  await part("left arm").turnTo(0);
  // head over to the tree
  await goTo(thing("tree-3"), 7);
});

forever(async () => {
  const seen = await look(10);
  if (seen && is(seen, "red")) {
    play("honk");
    await move(-5, 7); // back up
  }
});

const rainbow = ["red", "orange", "yellow", "green", "blue", "purple", "pink"];

onClick(async () => {
  // Everything floats!
  gravity(0);
  play("whoosh");
  say("Floaty time!", 2);
  await wait(5);

  // Gravity comes back
  gravity(1);
  play("drum");

  // Rain down rainbow bricks
  for (let i = 0; i < 14; i++) {
    spawn({ color: rainbow[i % rainbow.length], size: "2x2", at: place(random(-10, 10), random(-10, 10)) });
    await wait(0.15);
  }
  play("yay");
});
